import{_ as e,o as a,c as l,b6 as i}from"./chunks/framework.BUXTSoD9.js";const x=JSON.parse('{"title":"プロジェクト紹介","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/guide/introduction.md","filePath":"ja-jp/guide/introduction.md"}'),d={name:"ja-jp/guide/introduction.md"};function n(r,t,s,g,f,y){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="プロジェクト紹介" tabindex="-1">プロジェクト紹介 <a class="header-anchor" href="#プロジェクト紹介" aria-label="Permalink to “プロジェクト紹介”">​</a></h1><p>2025年は、多くの人にとってAIプログラミングの元年と呼ばれています。AIを使ってコードを書く人が増えていますが、その多くはまだおもちゃレベルにとどまっています。Vibe Codingで開発プロセスをどう組むか、どのツールを選ぶべきか、プロトタイプから本番運用までに何が足りないのか、わからないことが多いでしょう。</p><p>私たちは段階的な<strong>三段階の実践パス</strong>を採用しています。初心者向けステージではミニゲームでAIプログラミングに素早く慣れ、第一段階ではVibe Codingのワークフローを身につけWebアプリケーションのプロトタイプを完成させ、第二段階ではフルスタック開発とデプロイを学び、第三段階ではクロスプラットフォームの複雑なアプリケーションを構築します。</p><p>各ステージには完全なプロジェクト実践が含まれており、実際の課題の中でおもちゃから製品へと進化し、最終的に<strong>どんなアイデアも実用アプリとして具現化する能力</strong>を身につけます。</p><p>私たちは、Vibe Codingをマスターし、体系的なトレーニングを積めば、一人で<strong>フロントエンド・バックエンド開発、AI能力の統合、プロダクトデザインを兼ね備えたオールラウンド開発者</strong>になれると信じています。</p><p>本プロジェクトは主に3種類の学習者を対象としています：</p><ul><li><strong>初心者（一般の方 / プロダクト・運営側）</strong>：非技術背景の方や入門学習者が重要な概念を理解し、最初のAI小ツールやプロダクトプロトタイプを完成させるのを支援します。</li><li><strong>初中級開発者（基礎のある学生や開発者）</strong>：vibe codingとネイティブAIアプリケーション開発を体系的に習得します。</li><li><strong>上級開発者（企業・スタートアップ、オープンソース・独立開発者）</strong>：チームや個人がネイティブAIアプリケーションを迅速に構築・検証・反復できるよう支援します。</li></ul><h2 id="📖-コンテンツナビゲーション" tabindex="-1">📖 コンテンツナビゲーション <a class="header-anchor" href="#📖-コンテンツナビゲーション" aria-label="Permalink to “📖 コンテンツナビゲーション”">​</a></h2><h3 id="総付録" tabindex="-1">総付録 <a class="header-anchor" href="#総付録" aria-label="Permalink to “総付録”">​</a></h3><p><a href="/easy-vibe-ja-learning-map/ja-jp/appendix/8-artificial-intelligence/ai-capability-dictionary.html">AI能力辞典：一般的なAIコア概念と用語、シナリオの解説</a></p><h3 id="ゼロ、ようちえん" tabindex="-1">ゼロ、ようちえん <a class="header-anchor" href="#ゼロ、ようちえん" aria-label="Permalink to “ゼロ、ようちえん”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">キーコンテンツ</th><th style="text-align:left;">状態</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/learning-map/">初心者向け：学習マップ</a></td><td style="text-align:left;">全体学習パスガイド</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/ai-capabilities-through-games/">初心者向け：AI時代、話せばプログラミング</a></td><td style="text-align:left;">貪食蛇などのケースでAIプログラミングの能力を初体験</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="一、aiプロダクトマネージャー" tabindex="-1">一、AIプロダクトマネージャー <a class="header-anchor" href="#一、aiプロダクトマネージャー" aria-label="Permalink to “一、AIプロダクトマネージャー”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">キーコンテンツ</th><th style="text-align:left;">状態</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/introduction-to-ai-ide/">初級二：AI IDEツールを知る</a></td><td style="text-align:left;">IDEの使い方を学び、インターフェース構造と効率的なプロンプト方法を習得</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/building-prototype/">初級三：プロトタイプを作る</a></td><td style="text-align:left;">プロダクト分析の分解から、マルチページプロダクトプロトタイプ実装までの完全ループ</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/integrating-ai-capabilities/">初級四：プロトタイプにAI能力を追加</a></td><td style="text-align:left;">一般的なAI能力（テキスト・画像・動画）のAPI導入を理解し完了</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/complete-project-practice/">初級五：完全プロジェクト実践</a></td><td style="text-align:left;">実シナリオのシミュレーション、ユーザーフィードバックの反復とプロジェクト発表（課題あり）</td><td style="text-align:left;">✅</td></tr></tbody></table><h4 id="付録" tabindex="-1">付録 <a class="header-anchor" href="#付録" aria-label="Permalink to “付録”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">キーコンテンツ</th><th style="text-align:left;">状態</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/appendix-a-product-thinking/">付録A：プロダクト思考補足</a></td><td style="text-align:left;">アイデア評価からニーズ分解、MVPまでのプロダクト思考フレームワーク</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/appendix-b-common-errors/">付録B：よくあるエラーと解決策</a></td><td style="text-align:left;">vibe codingでのよくあるエラーとトラブルシューティング方法</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/appendix-idea-sources/">付録：アイデアの探し方</a></td><td style="text-align:left;">参考アプリ、トレンド、VCリストから細分化方向を見つける</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/appendix-double-diamond/">付録：ダブルダイヤモンドモデル</a></td><td style="text-align:left;">まず問題を定義し、それからソリューション設計を展開する完全リズムを理解</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/appendix-jobs-to-be-done/">付録：Jobs to Be Done</a></td><td style="text-align:left;">JTBD手法でユーザーが本当に達成したいことを見極める</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-1/appendix-mom-test/">付録：The Mom Testユーザーインタビュー法</a></td><td style="text-align:left;">ユーザーインタビューを通じてニーズを検証する調査方法</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="二、初中級開発エンジニア" tabindex="-1">二、初中級開発エンジニア <a class="header-anchor" href="#二、初中級開発エンジニア" aria-label="Permalink to “二、初中級開発エンジニア”">​</a></h3><h4 id="フロントエンド部分" tabindex="-1">フロントエンド部分 <a class="header-anchor" href="#フロントエンド部分" aria-label="Permalink to “フロントエンド部分”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">キーコンテンツ</th><th style="text-align:left;">状態</th></tr></thead><tbody><tr><td style="text-align:left;">lovartで素材制作</td><td style="text-align:left;">lovartを使って人物、シーンなどのビジュアル素材を一括生成し、UIデザインとフロントエンド開発に素材基盤を提供</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">FigmaとMasterGo入門</td><td style="text-align:left;">デザインツールで情報アーキテクチャとページ構造を整理し、フロントエンド実装の基盤を作る</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">最初のモダンアプリケーション構築 - UIデザイン</td><td style="text-align:left;">デザインカンプに基づいてコンポーネント化インターフェースを完成し、デザインからコードへの最初のリンクを実現</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">UIデザイン仕様を参考にページとボタンを設計</td><td style="text-align:left;">主要なデザイン仕様を使ってページ構造、ボタン階層を整理し、AIでデザイン案を生成する方法を学ぶ</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-2/frontend/hogwarts-portraits/">ホグワーツの肖像画を一緒に作ろう</a></td><td style="text-align:left;">ゼロからAI能力を組み込んだフロントエンドアプリを作り、デザインと開発を連携させる</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="バックエンド開発部分" tabindex="-1">バックエンド開発部分 <a class="header-anchor" href="#バックエンド開発部分" aria-label="Permalink to “バックエンド開発部分”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">キーコンテンツ</th><th style="text-align:left;">状態</th></tr></thead><tbody><tr><td style="text-align:left;">APIとは何か</td><td style="text-align:left;">HTTPインターフェースとリクエスト・レスポンスモデルを理解し、バックエンド統合と連携の準備</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-2/backend/database-supabase/">データベースからSupabaseまで</a></td><td style="text-align:left;">SupabaseでデータベースとAPIを構築し、データモデルとフロントエンドページを接続</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">大規模モデルでインターフェースコードとドキュメントを支援</td><td style="text-align:left;">大規模モデルでインターフェースとデータベースのドキュメントおよびコードを生成し、読みやすくテスト可能なバックエンドを実現</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">GitワークフローとZeaburデプロイ</td><td style="text-align:left;">Gitワークフローでコードを管理し、アプリケーションをZeaburにデプロイして公開</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">モダンCLI開発ツール</td><td style="text-align:left;">CLI系AIプログラミングツールで開発とデバッグを加速し、個人のエンジニアリングワークフローを形成</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">stripeなどの決済システムの統合方法</td><td style="text-align:left;">決済システムを導入し、課金フローと基本決済プロセスを完了</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">最初のモダンアプリケーション構築 - フルスタックアプリ</td><td style="text-align:left;">フロントエンド、バックエンド、決済モジュールを統合し、デプロイ可能なフルスタックWebアプリを完成</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">モダンフロントエンドコンポーネントライブラリ + Trae実戦</td><td style="text-align:left;">モダンフロントエンドコンポーネントライブラリとTraeを使い、ログイン登録と課金対応のプロダクトを独立して完成</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="ai能力付録" tabindex="-1">AI能力付録 <a class="header-anchor" href="#ai能力付録" aria-label="Permalink to “AI能力付録”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">キーコンテンツ</th><th style="text-align:left;">状態</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ja-jp/stage-2/ai-capabilities/dify-knowledge-base/">Dify入門とナレッジベース統合</a></td><td style="text-align:left;">Dify Workflowと基本RAGでツール系プロダクトを構築し、今後のアプリアップグレードのサンプルを作成</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">AI辞典の調べ方とマルチモーダルAPIの統合を学ぶ</td><td style="text-align:left;">適切なモデルとAPIの調べ方を学び、テキスト、画像などのマルチモーダル能力をプロダクトに組み込む</td><td style="text-align:left;">🚧</td></tr></tbody></table><h3 id="三、上級開発エンジニア" tabindex="-1">三、上級開発エンジニア <a class="header-anchor" href="#三、上級開発エンジニア" aria-label="Permalink to “三、上級開発エンジニア”">​</a></h3>',24)])])}const o=e(d,[["render",n]]);export{x as __pageData,o as default};
